const categories=[
 {id:'education-scholarships',name:'Education & Scholarships',desc:'Scholarships, student aid and education support',icon:'🎓',count:'Education services'},
 {id:'certificates',name:'Certificates',desc:'Income, caste, residence and other certificates',icon:'▣',count:'Official documents'},
 {id:'licenses-permits',name:'Licenses & Permits',desc:'Driving, trade and other permits',icon:'▤',count:'Licenses and permits'},
 {id:'benefits-subsidies',name:'Benefits & Subsidies',desc:'Welfare schemes and financial assistance',icon:'♡',count:'Benefits and support'},
 {id:'government-registrations',name:'Government Registrations',desc:'Public registrations and business services',icon:'▥',count:'Registration services'},
 {id:'other-services',name:'Other Services',desc:'Find a service or start a custom application',icon:'•••',count:'Custom discovery'}
];
const demoServices=[
 {id:'post-matric-scholarship',name:'Post-Matric Scholarship',state:'Maharashtra',stateCode:'maharashtra',department:'Social Justice & Special Assistance Department',category:'education-scholarships',desc:'Financial assistance for eligible students pursuing post-matriculation education.',availability:'available',mode:'native',applicationMode:'Online',icon:'🎓'},
 {id:'income-certificate-mh',name:'Income Certificate',state:'Maharashtra',stateCode:'maharashtra',department:'Revenue Department',category:'certificates',desc:'Information and application guidance for an official income certificate.',availability:'available',mode:'guided_only',applicationMode:'Online / Offline',icon:'▣'},
 {id:'driving-licence-mh',name:'Driving Licence',state:'Maharashtra',stateCode:'maharashtra',department:'Transport Department',category:'licenses-permits',desc:'Driving licence application and renewal information.',availability:'available',mode:'external_assisted',applicationMode:'Online',icon:'▤'},
 {id:'caste-certificate-bihar',name:'Caste Certificate',state:'Bihar',stateCode:'bihar',department:'Department to be verified',category:'certificates',desc:'Official caste-certificate service candidate. Verify department, issuing level, documents and portal before using this record as fact.',availability:'unknown',mode:'needs_verification',applicationMode:'Unknown',icon:'▣'},
 {id:'residence-certificate-bihar',name:'Residence Certificate',state:'Bihar',stateCode:'bihar',department:'Department to be verified',category:'certificates',desc:'Residence certificate service candidate; verify official source before presenting requirements.',availability:'unknown',mode:'needs_verification',applicationMode:'Unknown',icon:'▣'},
 {id:'ration-card-mh',name:'Ration Card Services',state:'Maharashtra',stateCode:'maharashtra',department:'Food, Civil Supplies and Consumer Protection',category:'benefits-subsidies',desc:'Information about ration card services and public distribution support.',availability:'unknown',mode:'guided_only',applicationMode:'Online / Offline',icon:'▤'}
];
let currentPage='dashboard';let selectedService=demoServices[0];let customResult=null;let isControlled=false;
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function navigate(page){currentPage=page;document.querySelectorAll('.nav-item').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.querySelectorAll('.dropdown').forEach(d=>d.hidden=true);document.querySelectorAll('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));render();window.scrollTo(0,0)}
function goHash(){let raw=location.hash.slice(1)||'dashboard';let [p,q]=raw.split('?');if(p==='custom')navigate('custom');else if(p==='services'){navigate('services');if(q){let params=new URLSearchParams(q);if(params.get('category'))$('#filterCategory').value=params.get('category');if(params.get('state'))$('#filterState').value=params.get('state');if(params.get('view'))$('#directoryView').textContent=params.get('view')==='state'?'Browse by State':params.get('view')==='department'?'Browse by Department':'All Services';filterServices()}}else if(p.startsWith('service/')){selectedService=demoServices.find(s=>s.id===p.split('/')[1])||demoServices[0];navigate('service-details')}else navigate(p)}
function badge(mode){const map={native:['Native in CivicFlow','green'],external_assisted:['External portal · Guided assistance','orange'],guided_only:['Official information only','blue'],not_integrated:['Not integrated',''],needs_verification:['Needs verification','red']};let x=map[mode]||['Unknown',''];return `<span class="tag ${x[1]}">${x[0]}</span>`}
function serviceCard(s){return `<article class="card service-card"><div class="service-icon">${s.icon}</div><div class="service-info"><h3>${esc(s.name)}</h3><p>${esc(s.desc)}</p><div class="meta"><span class="tag">${esc(s.state)}</span><span class="tag">${esc(s.category.replaceAll('-',' '))}</span>${badge(s.mode)}</div></div><div class="service-actions"><button class="btn btn-secondary" onclick="openService('${s.id}')">View details →</button></div></article>`}
function render(){const root=$('#appContent');const pages={dashboard:dashboardPage,'new-application':newPage,services:servicesPage,'service-details':detailsPage,custom:customPage,workspace:workspacePage,applications:applicationsPage,form:formPage,review:reviewPage,tracking:trackingPage,documents:()=>genericPage('Documents','Manage your document records, upload status and verification information.','▧'),approvals:()=>genericPage('Approvals','Review actions that require your explicit confirmation.','☑'),assistant:()=>genericPage('AI Assistant','Ask CivicFlow about a government service or start a custom application.','✧'),settings:()=>genericPage('Settings','Manage profile, language, notifications and account preferences.','⚙'),notifications:()=>genericPage('Notifications','Your service and application updates appear here.','♧')};root.innerHTML=(pages[currentPage]||dashboardPage)();if(currentPage==='services')filterServices()}
function dashboardPage(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow">YOUR DIGITAL PUBLIC SERVICE DESK</p><h1>A stronger connection<br>to public services.</h1><p>Accessible government services for every citizen.</p><button class="btn btn-primary" onclick="navigate('new-application')">Start a new application <span>→</span></button></div><img class="hero-art" src="../assets/04-temple-flag-hero-reference.png" alt="Temple building, Indian flag and tricolour ribbon illustration" /></section><div class="metrics"><div class="card metric"><div class="metric-icon">▤</div><div><strong>4</strong><span>Active Applications</span></div></div><div class="card metric"><div class="metric-icon">◷</div><div><strong>1</strong><span>In Review</span></div></div><div class="card metric"><div class="metric-icon">▧</div><div><strong>3</strong><span>Documents Pending</span></div></div><div class="card metric"><div class="metric-icon">!</div><div><strong>0</strong><span>Action Required</span></div></div></div><div class="dash-grid"><section class="card card-pad"><div class="section-title"><h2>Your Applications</h2><a class="text-link" href="#applications">View all →</a></div>${appRow('Post-Matric Scholarship','Maharashtra · EDU001','In Review','orange','2 days ago')}${appRow('Income Certificate','Maharashtra · CERT003','Draft','blue','4 days ago')}${appRow('Driving Licence','Maharashtra · LIC002','Submitted','green','10 days ago')}</section><section class="card card-pad"><div class="section-title"><h2>Quick Actions</h2></div>${quick('☆','Explore Services','Browse government services','services')}${quick('▧','Upload Documents','Manage your documents','documents')}${quick('✧','Ask AI Assistant','Get help with your application','assistant')}${quick('⌕','Track Application','Check application status','applications')}</section></div>`}
function appRow(name,sub,status,kind,ago){return `<div class="app-row"><div class="app-symbol">▤</div><div class="app-main"><b>${name}</b><small>${sub}</small></div><div class="app-meta"><span class="tag ${kind}">${status}</span><small>Updated ${ago}</small></div><span class="muted">›</span></div>`}
function quick(icon,name,desc,page){return `<a href="#${page}" class="quick-row"><span class="quick-ic">${icon}</span><span><b>${name}</b><small>${desc}</small></span><span class="arrow">›</span></a>`}
function newPage(){return `<div class="page-head"><div><p class="eyebrow">START A SERVICE APPLICATION</p><h1>What would you like to apply for?</h1><p>Choose a category to explore relevant government services.</p></div></div><label class="global-search" style="width:100%;margin-bottom:18px"><span>⌕</span><input id="categorySearch" placeholder="Search categories or services..." oninput="filterCategories(this.value)" /></label><div class="category-grid" id="categoryGrid">${categories.map(categoryCard).join('')}</div><div class="card custom-cta"><div><h3>Can't find your service?</h3><p>Describe what you need. CivicFlow can help discover the official service and guide you through a custom application.</p></div><button class="btn btn-primary" onclick="navigate('custom')">Create a custom application →</button></div>`}
function categoryCard(c){return `<button class="category-card" data-cat-name="${c.name.toLowerCase()}" onclick="location.hash='services?category=${c.id}'"><span class="category-ic">${c.icon}</span><span><b>${c.name}</b><small>${c.desc}</small><span class="linkish">Explore category →</span></span></button>`}
function filterCategories(v){document.querySelectorAll('.category-card').forEach(e=>e.classList.toggle('hidden',!e.dataset.catName.includes(v.toLowerCase())))}
function servicesPage(){return `<div class="page-head"><div><p class="eyebrow">DISCOVER · COMPARE · APPLY</p><h1>Explore Government Services</h1><p>Find services by state, department or category—or describe a service that isn't listed.</p></div><button class="btn btn-primary" onclick="navigate('custom')">＋ Custom application</button></div><div class="toolbar"><input class="field search-field" id="serviceSearch" placeholder="Search services, keywords or departments..." oninput="filterServices()"><select class="select" id="filterState" onchange="filterServices()"><option value="">All States / India</option><option value="maharashtra">Maharashtra</option><option value="bihar">Bihar</option><option value="uttar-pradesh">Uttar Pradesh</option></select><select class="select" id="filterDepartment" onchange="filterServices()"><option value="">All Departments</option><option value="Revenue Department">Revenue Department</option><option value="Transport Department">Transport Department</option><option value="General Administration Department">General Administration Department</option><option value="Social Justice & Special Assistance Department">Social Justice & Special Assistance Department</option></select></div><div class="category-grid" style="grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;margin-bottom:16px">${categories.map(c=>`<button class="card" style="padding:12px 9px;text-align:center;cursor:pointer" onclick="$('#filterCategory').value='${c.id}';filterServices()"><div style="font-size:22px">${c.icon}</div><b style="font-size:11px;display:block;margin:6px 0">${c.name}</b></button>`).join('')}</div><div class="directory-layout"><aside class="card filter-card"><div class="section-title"><h2>Filters</h2><button class="text-link" onclick="clearFilters()">Clear all</button></div><div class="filter-block"><label>Category</label><select id="filterCategory" class="select" onchange="filterServices()"><option value="">All categories</option>${categories.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></div><div class="filter-block"><label>Application mode</label><div class="filter-list"><label><input type="checkbox" onchange="filterServices()" class="mode-check" value="Online"> Online</label><label><input type="checkbox" onchange="filterServices()" class="mode-check" value="Offline"> Offline</label><label><input type="checkbox" onchange="filterServices()" class="mode-check" value="Online / Offline"> Both</label></div></div><div class="filter-block"><label>CivicFlow capability</label><div class="filter-list"><label><input type="checkbox" class="cap-check" value="native" onchange="filterServices()"> Native in CivicFlow</label><label><input type="checkbox" class="cap-check" value="external_assisted" onchange="filterServices()"> External guided</label><label><input type="checkbox" class="cap-check" value="guided_only" onchange="filterServices()"> Information only</label></div></div><div class="filter-block"><label>Browse by</label><button class="btn btn-secondary full" onclick="$('#filterState').focus()">⌖ Choose State</button><button class="btn btn-secondary full" style="margin-top:7px" onclick="$('#filterDepartment').focus()">▤ Choose Department</button></div></aside><section><div class="state-note" id="directoryView">Select a state and department to narrow results. A service being listed does not necessarily mean CivicFlow automates it.</div><div class="section-title"><h2>Matching services</h2><span class="small muted" id="resultCount">Showing services</span></div><div class="service-list" id="serviceResults"></div><div class="card custom-cta"><div><h3>Can't find your service?</h3><p>Tell CivicFlow what you need, including the state. We'll find an official route and open a custom application workspace when supported.</p></div><button class="btn btn-primary" onclick="navigate('custom')">Describe my service →</button></div></section></div>`}
function filterServices(){if(currentPage!=='services')return;const q=($('#serviceSearch')?.value||'').toLowerCase();const st=$('#filterState')?.value||'';const dep=$('#filterDepartment')?.value||'';const cat=$('#filterCategory')?.value||'';const modes=[...document.querySelectorAll('.mode-check:checked')].map(x=>x.value);const caps=[...document.querySelectorAll('.cap-check:checked')].map(x=>x.value);let arr=demoServices.filter(s=>(!q||[s.name,s.desc,s.department,s.state].join(' ').toLowerCase().includes(q))&&(!st||s.stateCode===st)&&(!dep||s.department===dep)&&(!cat||s.category===cat)&&(!modes.length||modes.includes(s.applicationMode))&&(!caps.length||caps.includes(s.mode)));$('#serviceResults').innerHTML=arr.length?arr.map(serviceCard).join(''):`<div class="card empty-state"><div class="empty-icon">⌕</div><h3>No matching services found</h3><p class="muted">Try a different state or search term, or start a custom application.</p><button class="btn btn-primary" onclick="navigate('custom')">Create custom application →</button></div>`;$('#resultCount').textContent=`${arr.length} result${arr.length===1?'':'s'} · illustrative prototype data`;let stateName=st?({bihar:'Bihar',maharashtra:'Maharashtra','uttar-pradesh':'Uttar Pradesh'}[st]):'All India';let view=$('#directoryView');if(view)view.textContent=`Showing ${stateName} services. Department choices should be sourced from the selected jurisdiction's verified service data.`}
function clearFilters(){['filterState','filterDepartment','filterCategory'].forEach(id=>{let e=$('#'+id);if(e)e.value=''});document.querySelectorAll('.mode-check,.cap-check').forEach(e=>e.checked=false);if($('#serviceSearch'))$('#serviceSearch').value='';filterServices()}
function openService(id){selectedService=demoServices.find(s=>s.id===id)||demoServices[0];location.hash='service/'+id}
function detailsPage(){let s=selectedService;return `<div class="page-head"><div><p class="eyebrow"><a href="#services">Explore Services</a> / ${s.category.replaceAll('-',' ')}</p><h1>${s.name}</h1><p>${s.state} · ${s.department}</p></div>${badge(s.mode)}</div><section class="card detail-hero"><div class="service-icon">${s.icon}</div><div style="flex:1"><h2 style="font:800 23px Manrope;margin:0 0 7px">${s.name}</h2><p class="muted" style="margin:0">${s.desc}</p><div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap"><span class="tag">${s.state}</span><span class="tag">${s.applicationMode}</span>${badge(s.mode)}</div></div></section><div class="two-col"><section class="card card-pad"><h2 style="font:750 18px Manrope">About this service</h2><p class="muted" style="line-height:1.6">This is an illustrative service detail. In production, show only details grounded in verified official sources, including eligibility, required documents, fees, process and dates.</p><div class="info-row"><b>State / Jurisdiction</b><span>${s.state}</span></div><div class="info-row"><b>Department</b><span>${s.department}</span></div><div class="info-row"><b>Application mode</b><span>${s.applicationMode}</span></div><div class="info-row"><b>CivicFlow capability</b><span>${s.mode}</span></div></section><section class="card card-pad"><h2 style="font:750 18px Manrope">What happens next?</h2><p class="muted small">CivicFlow will use the available capability level. It will not claim automation when only an official information page is available.</p><div class="capability-box"><b>${s.mode==='native'?'Native CivicFlow workflow':s.mode==='external_assisted'?'External portal with guided assistance':s.mode==='guided_only'?'Official information only':'Needs verification'}</b><p>${s.mode==='native'?'This service can use the existing CivicFlow application workflow.':s.mode==='external_assisted'?'A verified official portal can be opened in the browser workspace if the Browser Agent supports it.':'Verify the official source and capability before proceeding. A manual guidance path may be available.'}</p></div>${s.mode==='native'?`<button class="btn btn-primary full" onclick="navigate('workspace')">Apply Now →</button>`:`<button class="btn btn-primary full" onclick="navigate('custom')">Start guided / custom application →</button>`}<button class="btn btn-secondary full" style="margin-top:8px" onclick="navigate('services')">Back to services</button></section></div>`}
function customPage(){return `<div class="page-head"><div><p class="eyebrow">CUSTOM APPLICATION</p><h1>Tell CivicFlow what you need.</h1><p>Describe a government service—even when it is not already integrated in CivicFlow.</p></div><span class="tag green">AI-assisted discovery</span></div><div class="custom-grid"><section class="card card-pad"><h2 style="font:750 19px Manrope;margin:0">Describe your government service</h2><p class="muted small">Start with the service and state. Do not enter identity numbers, passwords, OTPs or upload sensitive documents at this stage.</p><label class="form-label" for="requestText">What service do you need? *</label><textarea id="requestText" class="textarea" placeholder="For example: I need a caste certificate in Bihar">I need a caste certificate in Bihar</textarea><label class="form-label" for="customState">State / jurisdiction *</label><select class="select full" id="customState"><option value="Bihar">Bihar</option><option value="Maharashtra">Maharashtra</option><option value="Uttar Pradesh">Uttar Pradesh</option><option value="Delhi">Delhi</option><option value="Other">Other / Not sure</option></select><label class="form-label" for="customDistrict">District (optional)</label><input class="field full" id="customDistrict" placeholder="Enter district if known"/><label class="form-label" for="customDept">Department (optional)</label><input class="field full" id="customDept" placeholder="If you know the department"/><button class="btn btn-primary full" style="margin-top:18px" onclick="runDiscovery()">Find my service and guide me →</button><p class="muted" style="font-size:11px;margin-top:12px">Illustrative prototype: the discovery result below is simulated. Production must call the AI discovery service and verify official government sources.</p></section><aside class="card result-panel" id="discoveryResult"><div class="big-icon">✧</div><h2 style="font:750 19px Manrope;margin:0 0 8px">How custom discovery works</h2><p class="muted small" style="line-height:1.6">CivicFlow interprets the service request, checks state and department context, verifies official sources and shows whether it can open the actual portal inside the application workspace.</p><div class="steps"><span class="step active">1. Describe</span><span class="step">2. Verify</span><span class="step">3. Open portal</span></div><div class="notice">Finding an official service does not automatically mean CivicFlow has implemented the browser automation.</div></aside></div>`}
function runDiscovery(){let request=$('#requestText').value;let state=$('#customState').value;let r=$('#discoveryResult');if(!request.trim()){alert('Describe the service first.');return}let isBihar=state==='Bihar'&&request.toLowerCase().includes('caste');r.innerHTML=`<div class="big-icon">${isBihar?'▣':'✧'}</div><span class="tag orange">${isBihar?'Candidate found · needs official verification':'Discovery required'}</span><h2 style="font:750 20px Manrope;margin:12px 0 6px">${isBihar?'Caste Certificate — Bihar':'Service discovery in progress'}</h2><p class="muted small">${isBihar?'The service candidate needs official source, department, issuing level and portal verification before it can be used.':'The request is ready to be sent to the AI service for state-specific official-source discovery.'}</p><div class="capability-box"><b>${isBihar?'Not yet verified / not a native integration':'No source result in this prototype'}</b><p>${isBihar?'This prototype does not establish the official authority or portal. Production must cite an official source and then check Browser Agent support.':'Connect the AI discovery endpoint and preserve the original request in the custom application record.'}</p></div><button class="btn btn-primary full" onclick="navigate('workspace')">Continue to custom workspace preview →</button><button class="btn btn-secondary full" style="margin-top:8px" onclick="navigate('services')">Back to service directory</button>`;customResult={request,state}}
function workspacePage(){return `<div class="page-head"><div><p class="eyebrow">CUSTOM APPLICATION · WORKSPACE</p><h1>Guided application workspace</h1><p>AI assistance, a government portal browser and application progress in one place.</p></div><span class="tag orange">Demo preview — not connected to a live portal</span></div><div class="workspace-grid"><aside class="card work-rail"><h3>Application progress</h3><p class="muted small">${customResult?.request||'Caste Certificate · Bihar'}</p><span class="tag">Custom application</span><div class="work-step active"><span class="step-no">1</span><span><b>Discover service</b><br><span class="muted">Review the service match</span></span></div><div class="work-step"><span class="step-no">2</span><span><b>Open official portal</b><br><span class="muted">Verify source and session</span></span></div><div class="work-step"><span class="step-no">3</span><span><b>Fill application</b><br><span class="muted">AI-guided field completion</span></span></div><div class="work-step"><span class="step-no">4</span><span><b>Review & submit</b><br><span class="muted">Citizen confirmation required</span></span></div><div class="notice">Portal session controls are simulated here. A real browser session must be connected to the Browser Agent.</div></aside><section class="card browser-card"><div class="browser-top"><span class="browser-dots"><i></i><i></i><i></i></span><span class="browser-address">No live portal session · Waiting for Browser Agent</span><span class="browser-status">DEMO</span></div><div class="browser-toolbar"><div><button class="btn btn-secondary" disabled>←</button> <button class="btn btn-secondary" disabled>→</button> <button class="btn btn-secondary" disabled>↻</button></div><div><button class="btn btn-secondary" onclick="toggleControl()">${isControlled?'Resume AI':'Take Control'}</button> <button class="btn btn-soft" onclick="alert('Prototype only: pause state is not connected to a browser session.')">Pause AI</button> <button class="btn btn-secondary" onclick="alert('No active browser session to stop.')">Stop</button></div></div><div class="browser-view"><div class="fake-portal"><div class="portal-head"><span class="portal-logo">CivicFlow browser area</span><span class="muted">Portal preview placeholder</span></div><div class="portal-title">Official government application portal will appear here</div><p class="small muted">When connected, this area renders the actual isolated Playwright session. Do not substitute an invented portal or static screenshot and call it live.</p><div class="fake-form-grid"><div>Applicant name<div class="fake-input">Enter directly in the live portal</div></div><div>Father's / Guardian's name<div class="fake-input">AI can suggest from approved profile data</div></div><div>Date of birth<div class="fake-input">Citizen review required</div></div><div>Certificate category<div class="fake-input">Inspect actual portal options</div></div></div><p class="browser-note">No data was entered or submitted in this prototype.</p></div></div></section><aside class="card ai-card"><div class="ai-header"><h3>✧ AI Assistant</h3><span class="tag green">Advisory</span></div><div class="ai-message">I can help understand the form and suggest values. The browser is not connected in this preview.</div><div class="ai-action"><span class="check">✓</span><span>Service request understood</span></div><div class="ai-action"><span class="check">✓</span><span>Official source verification required</span></div><div class="ai-action"><span>○</span><span>Browser page inspection pending</span></div><div class="ai-action"><span>○</span><span>Field mapping pending</span></div><div class="notice">Passwords, OTPs and CAPTCHA responses must be entered directly by the citizen. They are never sent to AI.</div><div class="ai-input"><input placeholder="Ask about the next step..." disabled><button class="btn btn-primary" disabled>Send</button></div></aside></div>`}
function toggleControl(){isControlled=!isControlled;alert(isControlled?'Take-control state toggled in prototype only.':'Resume state toggled in prototype only.')}
function applicationsPage(){return `<div class="page-head"><div><p class="eyebrow">YOUR SERVICES</p><h1>My Applications</h1><p>Continue, review and track every application independently.</p></div><button class="btn btn-primary" onclick="navigate('new-application')">＋ New Application</button></div><div class="card card-pad"><div class="section-title"><h2>All applications</h2><span class="tag">Illustrative sample data</span></div>${appRow('Post-Matric Scholarship','Maharashtra · EDU001','In Review','orange','2 days ago')}${appRow('Income Certificate','Maharashtra · CERT003','Draft','blue','4 days ago')}${appRow('Driving Licence','Maharashtra · LIC002','Submitted','green','10 days ago')}${appRow('Custom Caste Certificate Discovery','Bihar · Custom session','Needs verification','red','Just now')}</div>`}
function formPage(){return `<div class="page-head"><div><p class="eyebrow">APPLICATION FORM</p><h1>Complete your application</h1><p>Each field must use clear labels, validation and a per-application saved state.</p></div><span class="tag orange">Prototype example</span></div><section class="card card-pad"><div class="steps"><span class="step active">1. Applicant details</span><span class="step">2. Address</span><span class="step">3. Documents</span></div><div class="two-col"><div><label class="form-label">Applicant full name *</label><input class="field full" placeholder="Enter full name"><label class="form-label">Date of birth *</label><input class="field full" placeholder="DD/MM/YYYY"><label class="form-label">State *</label><select class="select full"><option>Select state</option><option>Maharashtra</option><option>Bihar</option></select></div><div><label class="form-label">Father / Guardian name</label><input class="field full" placeholder="Enter name"><label class="form-label">District</label><input class="field full" placeholder="Enter district"><div class="notice">The actual form fields must come from the selected service schema or live inspected portal—not generic assumptions.</div></div></div><button class="btn btn-primary" style="margin-top:18px" onclick="alert('Demo only: connect to application-specific store.')">Save and continue →</button></section>`}
function reviewPage(){return `<div class="page-head"><div><p class="eyebrow">FINAL REVIEW</p><h1>Review before proceeding</h1><p>Confirm that every required section is complete and accurate.</p></div></div><section class="card card-pad"><h2 style="font:750 19px Manrope">Application readiness</h2><p class="muted small">The real Core backend must enforce this review gate. Unchecking any required item must revoke readiness.</p>${['Applicant information','Address details','Required documents','Eligibility details','Field values reviewed'].map((x,i)=>`<label class="app-row"><input type="checkbox" ${i<3?'checked':''} onchange="$('#readyState').textContent='Review checklist changed — readiness must be recalculated by Core.'"><span>${x}</span></label>`).join('')}<label class="form-label"><input type="checkbox" id="declaration"> I confirm that I have reviewed the information and authorize the next action.</label><p id="readyState" class="muted small">Final submission requires a separate explicit confirmation.</p><button class="btn btn-primary" onclick="alert($('#declaration').checked?'Demo only: Core must validate all required checks.':'Please accept the declaration.')">Continue to approval</button></section>`}
function trackingPage(){return `<div class="page-head"><div><p class="eyebrow">APPLICATION STATUS</p><h1>Track your application</h1><p>Official status and evidence should be distinguished from demo or user-entered updates.</p></div><span class="tag orange">Status not verified</span></div><section class="card card-pad"><h2 style="font:750 19px Manrope">Application timeline</h2>${['Application created','Service details reviewed','Documents prepared','Awaiting official submission confirmation'].map((x,i)=>`<div class="work-step"><span class="step-no">${i+1}</span><span><b>${x}</b><br><span class="muted">${i===3?'Current state · not yet confirmed by a government portal':'Illustrative timeline event'}</span></span></div>`).join('')}</section>`}
function genericPage(title,desc,icon){return `<div class="page-head"><div><p class="eyebrow">CIVICFLOW</p><h1>${title}</h1><p>${desc}</p></div></div><section class="card empty-state"><div class="empty-icon">${icon}</div><h3>${title} interface reference</h3><p class="muted">This route is part of the full application redesign. Connect it to the existing CivicFlow features and state. This prototype page is intentionally minimal.</p><button class="btn btn-primary" onclick="navigate('dashboard')">Back to Dashboard</button></section>`}

document.querySelectorAll('[data-menu]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();const target=$('#'+btn.dataset.menu);const open=target.hidden;document.querySelectorAll('.dropdown').forEach(d=>d.hidden=true);document.querySelectorAll('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));target.hidden=!open;btn.setAttribute('aria-expanded',String(open))}));document.addEventListener('click',()=>{document.querySelectorAll('.dropdown').forEach(d=>d.hidden=true);document.querySelectorAll('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.dropdown').forEach(d=>d.hidden=true);document.querySelectorAll('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'))}});window.addEventListener('hashchange',goHash);$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){location.hash='services';setTimeout(()=>{let x=$('#serviceSearch');if(x){x.value=e.target.value;filterServices()}},0)}});goHash();
